// Generated by the AI Software Factory (internal/testharness) — do not edit: it
// is rewritten on every run. Prints one "PASS [e2e] <title>" or
// "FAIL [e2e] <title>: <why>" line per test — the lines the build gate counts
// and routes on — with the failure detail and spec location indented below.
'use strict';

const path = require('path');

// Colour codes (ESC [ … m) in Playwright's error messages.
const ANSI = new RegExp(String.fromCharCode(27) + '[[][0-9;]*m', 'g');

function clean(s) {
  return String(s || '').replace(ANSI, '').trim();
}

class AsfReporter {
  onBegin(config) {
    this.root = config.configFile ? path.dirname(config.configFile) : config.rootDir;
  }

  printsToStdio() {
    return true;
  }

  onTestEnd(test, result) {
    if (result.status === 'skipped') {
      console.log(`SKIP [e2e] ${test.title}`);
      return;
    }
    if (result.status === test.expectedStatus) {
      console.log(`PASS [e2e] ${test.title}`);
      return;
    }
    const errors = (result.errors && result.errors.length ? result.errors : [result.error]).filter(Boolean);
    const detail = errors.map((e) => clean(e.message || e.value || e.stack)).filter(Boolean).join('\n');
    const lines = detail.split('\n');
    console.log(`FAIL [e2e] ${test.title}: ${lines[0] || result.status}`);
    if (test.location && this.root) {
      console.log(`    at test/e2e/${path.relative(this.root, test.location.file)}:${test.location.line}`);
    }
    for (const line of lines.slice(1, 25)) {
      console.log(`    ${line}`);
    }
  }

  onError(error) {
    // A spec that fails to load (syntax error, bad import) never reaches onTestEnd.
    const first = clean(error.message || error.value || error.stack).split('\n')[0];
    console.log(`FAIL [e2e] (suite failed to load): ${first}`);
  }

  onEnd(result) {
    console.log(`== e2e run ${result.status}`);
  }
}

module.exports = AsfReporter;
